const rc=(a,b)=>ART['Cold Brew'].replace(/#1a0f08/g,a).replace(/#4a2a14/g,b);ART['Matcha Latte']=rc('#5f9e3e','#d6eebb');ART['Strawberry Frappé']=rc('#d6456f','#ffc2d4');ART['Blue Sky Latte']=rc('#3d6fe0','#c5d9ff');
const slug=m=>m.n.replace('é','e').replace(/ /g,'_');
const BASE=MENU.map(m=>({...m,k:slug(m),on:m.n}));
MENU.splice(0,MENU.length,...BASE.map(b=>({...b})));
let MOV={};
/* Menu photos are stored inside this file (IMGS) so the site works with just these 4 files. */
const IMGS={"Affogato": "data:image/jpeg;base64,", "Blue_Sky_Latte": "data:image/jpeg;base64,", "Cappuccino": "data:image/jpeg;base64,", "Caramel_Macchiato": "data:image/jpeg;base64,", "Cold_Brew": "data:image/jpeg;base64,", "Espresso": "data:image/jpeg;base64,", "Matcha_Latte": "data:image/jpeg;base64,", "Mocha": "data:image/jpeg;base64,", "Strawberry_Frappe": "data:image/jpeg;base64,"};
const imgOf=m=>m.img?(SB?SBURL+'/storage/v1/object/public/photos/'+m.img:'/_blob/'+m.img):(IMGS[m.k||slug(m)]||('img/'+(m.k||slug(m))+'.jpg'));
const clean=s=>String(s??'').replace(/[<>"&\\]/g,'').trim().slice(0,160);
function mergeItem(m,o){if(!o)return m;
 if(o.custom){m.custom=1;m.food=o.drink?0:1;m.e=o.drink?'☕':'🍽️'}
 if(o.n!=null&&clean(o.n))m.n=clean(o.n).slice(0,60);
 if(o.p!=null&&isFinite(+o.p))m.p=Math.max(0,Math.round(+o.p));
 if(o.d!=null)m.d=clean(o.d);
 if(o.t&&CATS.includes(o.t)&&o.t!='All')m.t=o.t;
 if(typeof o.img=='string'&&/^[\w-]{6,64}$/.test(o.img))m.img=o.img;
 m.so=!!o.so;m.st=(o.st!=null&&o.st!==''&&isFinite(+o.st))?Math.max(0,Math.round(+o.st)):null;m.sa=+o.sa||0;
 m.off=!!o.off;return m}
function applyMenu(){const ck=MENU[cur]?MENU[cur].k:null;const out=BASE.map(b=>mergeItem({...b},MOV[b.k]));
 Object.entries(MOV).filter(([k,o])=>o&&o.custom).sort((a,b)=>(a[1].created||0)-(b[1].created||0)).forEach(([k,o])=>out.push(mergeItem({k,on:'',custom:1,food:1,e:'☕',c:'#2a160c',g:'#c8873a',l:'#2a1208',f:'#f3e3cf',t:'Hot',n:'New item',p:0,d:''},o)));
 MENU.splice(0,MENU.length,...out);const ix=ck?MENU.findIndex(m=>m.k==ck):-1;cur=ix>=0?ix:0}
const blankArt=m=>`<svg class="ph" viewBox="0 0 300 300"><rect width="300" height="300" fill="${m.f||'#f3e3cf'}"/><text x="150" y="195" text-anchor="middle" font-size="120">${m.e||'☕'}</text></svg>`;
const FOODART={
"Chocolate Cake":`<svg class="ph" viewBox="0 0 300 300"><rect width="300" height="300" fill="#f1ddc7"/><ellipse cx="150" cy="238" rx="122" ry="24" fill="#fff"/><ellipse cx="150" cy="234" rx="96" ry="16" fill="#ece0d2"/><path d="M78 150h144v74q-72 24 -144 0z" fill="#4b2717"/><rect x="78" y="182" width="144" height="12" fill="#f4d9a8"/><path d="M78 150q72 -36 144 0v14q-12 22 -24 0q-10 24 -22 2q-12 22 -26 0q-12 24 -24 0q-12 20 -24 -2q-12 18 -24 0z" fill="#2a130a"/><circle cx="150" cy="122" r="16" fill="#d8283f"/><path d="M150 108q8 -20 22 -24" stroke="#3a7a2a" stroke-width="4" fill="none" stroke-linecap="round"/><ellipse cx="144" cy="117" rx="5" ry="3.5" fill="#fff" opacity=".6"/></svg>`,
"Cheesecake":`<svg class="ph" viewBox="0 0 300 300"><rect width="300" height="300" fill="#fbe8ec"/><ellipse cx="150" cy="238" rx="122" ry="24" fill="#fff"/><path d="M82 160h136v62q-68 22 -136 0z" fill="#fff1c9"/><rect x="82" y="206" width="136" height="16" fill="#b9793f"/><path d="M82 160q68 -34 136 0v10q-10 22 -22 0q-9 24 -20 2q-12 22 -26 0q-12 22 -24 -2q-12 18 -22 0q-10 14 -22 0z" fill="#e0476b"/><circle cx="150" cy="130" r="17" fill="#e0476b"/><path d="M142 118q8 -10 16 0" stroke="#3a7a2a" stroke-width="5" fill="none" stroke-linecap="round"/></svg>`,
"Butter Croissant":`<svg class="ph" viewBox="0 0 300 300"><rect width="300" height="300" fill="#f6e4c4"/><ellipse cx="150" cy="238" rx="120" ry="22" fill="#fff"/><g fill="#d79a45" stroke="#a8641c" stroke-width="3"><ellipse cx="70" cy="188" rx="30" ry="20" transform="rotate(40 70 188)"/><ellipse cx="230" cy="188" rx="30" ry="20" transform="rotate(-40 230 188)"/><ellipse cx="102" cy="160" rx="38" ry="26" transform="rotate(25 102 160)"/><ellipse cx="198" cy="160" rx="38" ry="26" transform="rotate(-25 198 160)"/><ellipse cx="150" cy="148" rx="48" ry="34"/></g><g stroke="#a8641c" stroke-width="3" fill="none" stroke-linecap="round" opacity=".6"><path d="M128 120q-6 28 2 56"/><path d="M172 120q6 28 -2 56"/><path d="M92 140q-4 22 8 40"/><path d="M208 140q4 22 -8 40"/></g><ellipse cx="136" cy="130" rx="14" ry="6" fill="#fff" opacity=".35"/></svg>`,
"Club Sandwich":`<svg class="ph" viewBox="0 0 300 300"><rect width="300" height="300" fill="#e8f0da"/><ellipse cx="150" cy="240" rx="124" ry="24" fill="#fff"/><rect x="80" y="196" width="140" height="26" rx="8" fill="#e8c385" stroke="#b98a46" stroke-width="3"/><path d="M76 196q14 -14 28 0t28 0t28 0t28 0t28 0" fill="#6cb04a"/><rect x="82" y="172" width="136" height="14" rx="5" fill="#e8483c"/><rect x="80" y="156" width="140" height="16" rx="6" fill="#f7e2b8"/><rect x="82" y="146" width="136" height="10" rx="4" fill="#f1b0a8"/><rect x="80" y="120" width="140" height="28" rx="10" fill="#e8c385" stroke="#b98a46" stroke-width="3"/><path d="M190 60L170 120" stroke="#c8873a" stroke-width="5" stroke-linecap="round"/><circle cx="192" cy="58" r="8" fill="#d8283f"/></svg>`};
const cup=m=>(m.img||!(m.custom||m.food))?`<img class="ph" src="${imgOf(m)}" alt="${m.n}" decoding="async">`:(m.custom?blankArt(m):(FOODART[m.on]||blankArt(m)));
const thumb=m=>(m.img||!(m.custom||m.food))?`<img class="tp" src="${imgOf(m)}" alt="" loading="lazy">`:`<span class="tp fe">${m.e||'☕'}</span>`;
MENU.forEach(m=>{if(!m.food){const i=new Image();i.src=imgOf(m)}});
$('cup3d').innerHTML=`<img class="ph hp" src="${imgOf(MENU[1])}" alt="${MENU[1].n}" decoding="async">`;
const st=$('stage');st.onmousemove=e=>{const r=st.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;$('cup3d').style.transform=`rotateY(${x*40}deg) rotateX(${-y*30}deg)`};st.onmouseleave=()=>$('cup3d').style.transform='';
let cur=1,cart=[];
let flt='All',prevI=-1;const CATS=['All','Hot','Cold','Dessert','Bites'];
function calcSold(){if(SB&&!sbAdmin)return;SOLD={};data.orders.forEach(o=>{(Array.isArray(o.lines)?o.lines:[]).forEach(l=>{if(l&&l.n)(SOLD[l.n]=SOLD[l.n]||[]).push([o.created||0,+l.q||0])})})}
const left=m=>{if(m.st==null)return null;const u=(SOLD[m.n]||[]).reduce((a,x)=>a+(x[0]>=m.sa?x[1]:0),0);return Math.max(0,m.st-u)};
const out=m=>!!m.so||left(m)===0;
const vis=()=>{const q=($('q').value||'').trim().toLowerCase();return MENU.map((m,i)=>i).filter(i=>!MENU[i].off&&(flt=='All'||MENU[i].t==flt)&&(!q||(MENU[i].n+' '+MENU[i].d).toLowerCase().includes(q)))};
function cats(){$('cats').innerHTML=CATS.map(c=>`<button class="chip ${c==flt?'on':''}" onclick="setFlt('${c}')">${c}</button>`).join('')}
function setFlt(c){flt=c;cats();const v=vis();show(v.includes(cur)?cur:(v.length?v[0]:cur))}
function show(i){cur=i;const m=MENU[i];if(prevI!==i){wipe(m.c);prevI=i}$('glow').style.backgroundColor=m.g;const rs=document.documentElement.style;rs.setProperty('--a',m.g);rs.setProperty('--b',m.f);$('glow2').style.backgroundColor=m.g;$('glow3').style.backgroundColor=m.f;
 const v=vis();$('pick').innerHTML=v.length?v.map(j=>`<button class="chip ${j==i?'on':''}" onclick="show(${j})">${thumb(MENU[j])}${MENU[j].n}${out(MENU[j])?' <small class="tag">· sold out</small>':''}</button>`).join(''):'<p class="tag">Nothing matches your search.</p>';
 $('info').innerHTML=`<div class="fade"><h3>${m.n}</h3><div class="price">Rs. ${m.p.toLocaleString()}${m.food?'':' <small class="tag">· medium</small>'}</div><p style="color:var(--mute);max-width:420px;margin-bottom:22px">${m.d}</p>${out(m)?'<button class="btn" disabled style="opacity:.5;cursor:not-allowed">Sold out today</button>':`<button class="btn" onclick="add(${i})">${m.food?'Add to order +':'Customize & add +'}</button>`}${(left(m)!=null&&left(m)>0&&left(m)<=5)?`<p class="tag" style="margin-top:10px">🔥 Only ${left(m)} left</p>`:''}</div>`;
 $('big').innerHTML=`${out(m)?'<div class="soldtag">SOLD OUT</div>':''}<div class="fade">${cup(m)}</div>`}
const SZ={Small:-100,Medium:0,Large:200},MK={Regular:0,Oat:150,Almond:150,Soy:100},SG=['No sugar','Less','Normal','Extra'];
const optText=(o,m)=>[o.size,(m&&m.nm)?null:o.milk+' milk',o.sugar+' sugar',o.shot?'extra shot':null].filter(Boolean).join(' · ');
const unitPrice=(m,o)=>m.p+(o?SZ[o.size]+MK[o.milk]+(o.shot?200:0):0);
function addLine(i,o){const m=MENU[i],k=i+'|'+JSON.stringify(o),f=cart.find(l=>l.k==k);if(out(m))return toast(m.n+' is sold out');const lf=left(m);if(lf!=null&&cart.filter(l=>l.i==i).reduce((a,l)=>a+l.q,0)>=lf)return toast('Only '+lf+' left of '+m.n);if(f)f.q++;else cart.push({k,i,o,u:unitPrice(m,o),q:1});upd();toast(m.n+' added')}
function add(i){MENU[i].food?addLine(i,null):openCust(i)}
function chg(x,d){if(d>0){const m=MENU[cart[x].i],lf=left(m);if(lf!=null&&cart.filter(l=>l.i==cart[x].i).reduce((a,l)=>a+l.q,0)>=lf)return toast('Only '+lf+' left of '+m.n)}cart[x].q+=d;if(cart[x].q<=0)cart.splice(x,1);upd()}
function upd(){let n=0,t=0,h='';cart.forEach((l,x)=>{const m=MENU[l.i];n+=l.q;t+=l.u*l.q;h+=`<div class="row"><span>${m.n}${l.o?`<small class="tag" style="display:block">${optText(l.o,m)}</small>`:''}</span><span><button onclick="chg(${x},-1)">−</button> ${l.q} <button onclick="chg(${x},1)">+</button></span><span>${(l.u*l.q).toLocaleString()}</span></div>`});
 $('lines').innerHTML=h||'<p class="tag">Your cart is empty.</p>';const dn=cart.reduce((a,l)=>a+(MENU[l.i].food?0:l.q),0);if($('earn'))$('earn').textContent=dn?'⭐ This order earns '+dn+' loyalty stamp'+(dn>1?'s':'')+' (added once collected)':'';$('cc').textContent=n;$('ct').textContent=t.toLocaleString();$('tot').textContent=t.toLocaleString()}
const drawer=o=>$('dr').classList.toggle('open',!!o);
