async function sbDel(c,id){if(!sbAdmin)throw new Error('not allowed');const r=await SB.from('kv').delete().eq('collection',c).eq('id',id);if(r.error)throw r.error}
function sbWatch(c,id,cb,eb){let dead=false,t=null,ch=null;
 const load=async()=>{if(dead)return;try{if(id===null)cb(qsOf(await sbList(c)));else{const d=await sbGet(c,id);cb({id,exists:d!==null,data:()=>d})}}catch(e){if(eb)eb(e)}};
 const kick=()=>{clearTimeout(t);t=setTimeout(load,150)};
 load();try{ch=SB.channel('kv-'+c+'-'+(id||'all')+'-'+Math.random().toString(36).slice(2,7)).on('postgres_changes',{event:'*',schema:'public',table:'kv',filter:'collection=eq.'+c},kick).subscribe()}catch(e){}
 const poll=setInterval(()=>{if(!document.hidden)load()},30000);
 return()=>{dead=true;clearInterval(poll);clearTimeout(t);try{if(ch)SB.removeChannel(ch)}catch(e){}}}
