 doc:id=>({get:async()=>{const d=await sbGet(c,id);return{id,exists:d!==null,data:()=>d}},set:d=>sbSet(c,id,d),delete:()=>sbDel(c,id),onSnapshot:(cb,eb)=>sbWatch(c,id,cb,eb)}),
