const SALT='mycoffee-admin-v1:',HU='b1f0cb96bcaf9e3189dd2e9a489388407dd94cd0bde26e33a2ebd13e6b9b2fe2',HP='988cf149af36d98b020f889ed6837957c83c40cbfacbdc7b78d37e7d904b7e74';
